import { useState } from 'react';
import {
  JxTextField,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
} from '@jinx-ui/react';

interface ProfileSettings {
  name: string;
  language: 'ru' | 'en';
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  initialName?: string;
  initialLanguage?: 'ru' | 'en';
  initialEmailNotifications?: boolean;
  onSave: (settings: ProfileSettings) => void;
}

export default function ProfileSettingsForm({
  initialName = '',
  initialLanguage = 'ru',
  initialEmailNotifications = true,
  onSave,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialName);
  const [language, setLanguage] = useState<'ru' | 'en'>(initialLanguage);
  const [emailNotifications, setEmailNotifications] = useState(
    initialEmailNotifications
  );

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <form
      className="jx-stack jx-gap-4"
      style={{ maxWidth: 'var(--jx-size-md)' }}
      onSubmit={handleSubmit}
    >
      <JxTextField
        label="Имя"
        value={name}
        onValueChange={setName}
        placeholder="Введите имя"
        required
      />

      <JxSelect
        label="Язык интерфейса"
        value={language}
        onValueChange={(value) => setLanguage(value as 'ru' | 'en')}
      >
        <JxSelectOption value="ru">Русский</JxSelectOption>
        <JxSelectOption value="en">English</JxSelectOption>
      </JxSelect>

      <JxSwitch
        checked={emailNotifications}
        onCheckedChange={setEmailNotifications}
      >
        Уведомления на почту
      </JxSwitch>

      <JxButton type="submit" variant="primary">
        Сохранить
      </JxButton>
    </form>
  );
}

